class Producto {
    String nombre;
    double precio;
    Producto(String n, double p) { nombre = n; precio = p; }
}

class Pedido {
    Producto[] productos = new Producto[10];
    int cantidad = 0;
    void agregarProducto(Producto p) { if (cantidad < 10) productos[cantidad++] = p; }
    double total() { double s = 0; for (int i = 0; i < cantidad; i++) s += productos[i].precio; return s; }
    void mostrar() {
        System.out.println("Pedido:");
        for (int i = 0; i < cantidad; i++)
            System.out.println("  - " + productos[i].nombre + ": $" + productos[i].precio);
        System.out.println("Total: $" + total());
    }
}

public class Main {
    public static void main(String[] args) {
        Producto p1 = new Producto("Laptop", 1200);
        Producto p2 = new Producto("Mouse", 25);
        Pedido pedido = new Pedido();
        pedido.agregarProducto(p1);
        pedido.agregarProducto(p2);
        pedido.mostrar();
    }
}

