class Paciente {
    String nombre;
    Paciente(String n) { nombre = n; }
}

class Consulta {
    Paciente paciente;
    String diagnostico;
    Consulta(Paciente p, String d) { paciente = p; diagnostico = d; }
    void mostrar() { System.out.println("Consulta: " + paciente.nombre + " - " + diagnostico); }
}

class Doctor {
    String nombre;
    Doctor(String n) { nombre = n; }
    Consulta atender(Paciente p, String d) {
        System.out.println(nombre + " atiende a " + p.nombre);
        return new Consulta(p, d);
    }
}

class Hospital {
    String nombre;
    Consulta[] consultas = new Consulta[10];
    int cantidad = 0;
    Hospital(String n) { nombre = n; }
    void agregarConsulta(Consulta c) { if (cantidad < 10) consultas[cantidad++] = c; }
    void mostrar() {
        System.out.println("Hospital: " + nombre);
        for (int i = 0; i < cantidad; i++) consultas[i].mostrar();
    }
}

public class Main {
    public static void main(String[] args) {
        Doctor doc = new Doctor("Dr. Perez");
        Hospital hospital = new Hospital("Hospital Central");
        Consulta c1 = doc.atender(new Paciente("Ana"), "Dolor de pecho");
        Consulta c2 = doc.atender(new Paciente("Luis"), "Check-up");
        hospital.agregarConsulta(c1);
        hospital.agregarConsulta(c2);
        hospital.mostrar();
    }
}
